/* Tile 2 rises over tile 1, then Nucleux picks the three building blocks. */
const { seg, eio, lerp } = kit;
const RISE = 0.65, PLAY = 0.5;
kit.scene('patterns', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground"></div>'));
    this.t1 = window.HWF.tile(kit, 0, 3);
    this.t2 = window.HWF.tile(kit, 1, 0);
    window.HWF.mark(kit, 'patterns');   /* the wordmark, where the intro left it */
  },
  render(t) {
    const p = eio(seg(t, 0, RISE));
    /* tile 1 as the last scene left it (pushed 1.2%), settling back under */
    this.t1.s.transform = 'scale(' + lerp(1.01225, 0.97, p).toFixed(4) + ')';
    this.t1.shade.opacity = (0.035 * p).toFixed(4);
    this.t2.s.transform = 'translateY(' + lerp(1080 - 132, 0, p).toFixed(1) + 'px) scale(' + (1 + 0.0035 * Math.max(0, t - RISE)).toFixed(4) + ')';
    this.t2.scene.render(Math.max(0, t - PLAY));
  },
});
